// Spring-based (natural, responsive)
const spring = useSpring({
  x: isOpen ? 100 : 0,
  config: { tension: 170, friction: 26 }
})

// Duration-based (precise timing)
const duration = useSpring({
  x: isOpen ? 100 : 0,
  config: { duration: 300, easing: easings.easeOutQuad }
})

// Try clicking rapidly:
// Spring: Smoothly reverses mid-animation
// Duration: Feels abrupt or jumpy

// 1. Start with preset
const springs = useSpring({
  x: 100,
  config: config.default
})

// 2. Too slow? Make it snappier
config: config.stiff  // Faster

// 3. Too bouncy? Add friction
config: { ...config.stiff, friction: 30 }

// 4. Still not right? Use frequency/damping
config: {
  frequency: 2,    // 2 bounces/second
  damping: 0.7     // Slight bounce
}

// Think: "I want a heavy drawer that slides smoothly"
const drawer = useSpring({
  x: isOpen ? 300 : 0,
  config: {
    mass: 3,        // Heavy (weighty feel)
    tension: 200,   // Moderate speed
    friction: 40,   // Smooth stop, no bounce
  }
})

// Think: "I want a bouncy button that responds quickly"
const button = useSpring({
  scale: isPressed ? 0.95 : 1,
  config: {
    mass: 0.5,      // Light (snappy feel)
    tension: 300,   // Very fast
    friction: 10,   // Let it bounce
  }
})
